<?php
$adminTitle='Audit log';require __DIR__.'/_header.php';$pdo=db();$ready=$pdo&&audit_schema_ready($pdo);$q=trim((string)($_GET['q']??''));$action=trim((string)($_GET['action']??''));$rows=[];
if($ready){$where=[];$params=[];if($q!==''){$where[]='(l.entity_type LIKE :q OR l.entity_id LIKE :q OR l.summary LIKE :q OR u.email LIKE :q)';$params['q']='%'.$q.'%';}if($action!==''){$where[]='l.action=:action';$params['action']=$action;}$sql='SELECT l.*,u.email admin_email,u.display_name FROM admin_audit_log l LEFT JOIN admin_users u ON u.id=l.admin_user_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY l.created_at DESC,l.id DESC LIMIT 500';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();}
?>
<div class="admin-heading"><div><div class="eyebrow">Governance</div><h1>Admin audit log</h1></div></div><?php if(!$ready):?><div class="alert error">V8 audit logging is not installed.</div><?php else:?><form method="get" class="card inline-select"><input name="q" value="<?= e($q) ?>" placeholder="Entity, ID, summary or admin"><input name="action" value="<?= e($action) ?>" placeholder="Exact action (optional)"><button class="btn">Filter</button></form><section class="card admin-section-gap"><div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Admin</th><th>Action</th><th>Entity</th><th>Summary</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?= e($row['created_at']) ?></td><td><?= e($row['display_name']?:$row['admin_email']?:'System') ?></td><td><code><?= e($row['action']) ?></code></td><td><?= e($row['entity_type']) ?><?= $row['entity_id']?' · '.e($row['entity_id']):'' ?></td><td><?= e($row['summary']) ?><?php if($row['metadata_json']):?><details><summary class="small muted">metadata</summary><pre class="audit-json"><?= e($row['metadata_json']) ?></pre></details><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">No matching audit records.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?><?php require __DIR__.'/_footer.php';?>
